# Generated by 2sc from function 'gccleaner'.
# This command is intentionally Pro-only: the Docker backup is the sole source.
if (-not (Get-Command -Name 'Initialize-CodexProfileFunctions' -CommandType Function -ErrorAction SilentlyContinue)) {
    $__profileModule = Join-Path ([Environment]::GetFolderPath('UserProfile')) 'Documents\WindowsPowerShell\Modules\CodexProfileFunctions\CodexProfileFunctions.psd1'
    if (-not (Test-Path -LiteralPath $__profileModule -PathType Leaf)) {
        throw "gccleaner requires the Codex profile module: $__profileModule"
    }
    Import-Module -Name $__profileModule -DisableNameChecking -ErrorAction Stop
    Initialize-CodexProfileFunctions
}

function gccleaner {
    [CmdletBinding()]
    param([switch]$SelfTest)

    $appName = 'ccleaner'
    $target = 'F:\backup\windowsapps\installed\ccleaner'
    $restoreCommand = Get-Command -Name 'Invoke-BackupDockerInstalledAppRestore' -CommandType Function -ErrorAction SilentlyContinue
    if (-not $restoreCommand -or -not $restoreCommand.Parameters.ContainsKey('RequirePro')) {
        throw 'gccleaner requires the Pro-only Docker restore helper.'
    }
    if ($SelfTest) {
        $imageRef = Get-BackupDockerLatestImageRef -Name $appName
        if ($imageRef -notmatch '(?i)windowsapps-installed-ccleaner') { throw "gccleaner resolved an unexpected image: $imageRef" }
        Write-Host 'GCCLEANER_SELFTEST_OK source=docker-container edition=pro fallbackInstaller=false' -ForegroundColor Green
        return
    }

    $startedAt = Get-Date
    $ccService = Get-Service -Name 'CCleanerPerformanceOptimizerService' -ErrorAction SilentlyContinue
    if ($ccService -and $ccService.Status -ne 'Stopped') {
        try { Stop-Service -InputObject $ccService -Force -ErrorAction Stop }
        catch { throw 'gccleaner requires an elevated PowerShell session to stop CCleaner Performance Optimizer Service before replacing the Pro payload.' }
    }
    Get-Process -Name 'CCleaner64', 'CCleaner', 'CCleanerPerformanceOptimizerService', 'CCleanerReactivator' -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
    $ccService = Get-Service -Name 'CCleanerPerformanceOptimizerService' -ErrorAction SilentlyContinue
    if ($ccService -and $ccService.Status -ne 'Stopped') { throw 'gccleaner could not stop CCleaner Performance Optimizer Service; the existing Pro installation was left unchanged.' }
    Write-Host 'GCCLEANER_PROGRESS stage=restoring-pro source=docker-container edition=pro' -ForegroundColor Cyan
    Invoke-BackupDockerInstalledAppRestore -Name $appName -RequirePro
    $exe = Join-Path $target 'CCleaner64.exe'
    if (-not (Test-Path -LiteralPath $exe -PathType Leaf)) { throw "gccleaner Pro restore completed but CCleaner64.exe is missing: $exe" }
    $elapsedMs = [int]((Get-Date) - $startedAt).TotalMilliseconds
    Write-Host "GCCLEANER_OK edition=pro source=docker-container path=$exe elapsed_ms=$elapsedMs" -ForegroundColor Green
}

if ($MyInvocation.InvocationName -ne '.') {
    & 'gccleaner' @args
}
